<template>
    <div>
        <h2>Import Format No,Premise Number,Name,Telephone no,IC No   BUKIT OUG CONDOMINIUM</h2>
        <button @click="exportData">Name,Phone,Email  Import Data</button>
        
        <!-- Progress bar -->
        <div v-if="isExporting" style="margin: 10px 0;">
            <div style="background-color: #f3f3f3; border-radius: 8px; overflow: hidden; height: 24px;">
                <div :style="{ width: progress + '%', backgroundColor: '#4caf50', height: '100%' }"></div>
            </div>
            <p>{{ progress }}% completed</p>
        </div>

        <table @paste="handlePaste">
            <thead>
                <tr>
                    <th v-for="(col, colIndex) in columns" :key="'header-' + colIndex">
                        Column {{ colIndex + 1 }}
                    </th>
                </tr>
            </thead>
            <tbody>
                <tr v-for="(row, rowIndex) in rows" :key="'row-' + rowIndex">
                    <td v-for="(cell, colIndex) in row" :key="'cell-' + rowIndex + '-' + colIndex">
                        <input v-model="rows[rowIndex][colIndex]" placeholder="Enter data" />
                    </td>
                </tr>
            </tbody>
        </table>

        <div v-if="exportedData.length">
            <h3>Exported Data</h3>
            <pre>{{ exportedData }}</pre>
        </div>
    </div>
</template>

<script>
import { ref } from 'vue';
import { convertDMY2YMD,createOrUpdateContactByKeys } from '../utils/contactUtils'; // Adjust the import path

export default {
    setup() {
        const defaultColumnCount = 5;
        const defaultRowCount = 1500;
        const columns = ref(new Array(defaultColumnCount).fill(1).map((_, i) => i + 1));
        const rows = ref(new Array(defaultRowCount).fill(null).map(() => new Array(defaultColumnCount).fill('')));
        const exportedData = ref([]);
        const progress = ref(0);
        const isExporting = ref(false);

        const handlePaste = (event) => {
            event.preventDefault();
            const clipboardData = event.clipboardData.getData('text');
            const rowsData = clipboardData.split('\n').map(row => row.split('\t'));

            rowsData.forEach((rowData, rowIndex) => {
                rowData.forEach((cellData, colIndex) => {
                    if (rowIndex < rows.value.length && colIndex < columns.value.length) {
                        rows.value[rowIndex][colIndex] = cellData;
                    }
                });
            });
        };

        const exportData = async () => {
            const formattedDate = new Date().toLocaleDateString("en-GB");
            exportedData.value = rows.value.map((row, rowIndex) => {
                const rowData = {};
                rowData[`no`] = rowIndex + 3;
                rowData[`project`] = "BUKIT OUG CONDOMINIUM";
                rowData[`sourceDate`] = convertDMY2YMD(formattedDate);
                row.forEach((cell, colIndex) => {
                    if (colIndex == 0) rowData[`no`] = parseInt(cell);
                    if (colIndex == 1) rowData[`address`] = cell;
                    if (colIndex == 2) rowData[`name`] = cell;
                    if (colIndex == 3) rowData[`name`] += " " + cell;
                    if (colIndex == 4) rowData[`phoneNumber`] = cell;
                 //   if (colIndex == 5) rowData[`IC`] += cell;
                   
                });
                return rowData;
            });

            isExporting.value = true;
            progress.value = 0;

            // Loop through each contact and update progress
            for (let i = 0; i < exportedData.value.length; i++) {
                const contactData = exportedData.value[i];

                if (!contactData.phoneNumber && !contactData.name) {
                    break; // Exit the loop if phoneNumber is blank
                }

                if (!contactData.phoneNumber) {
                   continue; // Exit the loop if phoneNumber is blank
                }
                try {
                    await createOrUpdateContactByKeys(contactData); // API call to backend
                    progress.value = Math.round(((i + 1) / exportedData.value.length) * 100);
                } catch (error) {
                    console.error('Error importing data:', error);
                }
            }

            isExporting.value = false;
            alert('Data exported and sent to Strapi. Check console for details.');
        };

        return {
            rows,
            columns,
            exportedData,
            progress,
            isExporting,
            handlePaste,
            exportData,
        };
    },
};
</script>

<style scoped>
table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 20px;
}

th, td {
    border: 1px solid #ddd;
    padding: 8px;
}

input {
    width: 100%;
    padding: 4px;
    box-sizing: border-box;
}

button {
    margin: 5px;
}
</style>
