<template>
  <v-container>
    <v-toolbar color="primary" dark>
      <v-toolbar-title>part 2</v-toolbar-title>
    </v-toolbar>



    <v-data-table v-model="gridData" :headers="headers" :items="gridData" item-value="id" class="elevation-1"
      @paste="handlePaste">

      <template v-slot:no-data>
        <v-btn @click="updateRow">Update Header Line - sec B</v-btn>
        <h1>{{projectId}}</h1>
      </template>
    </v-data-table>



    <v-progress-linear v-if="loading" indeterminate color="primary"></v-progress-linear>



    <!-- Dialog for PasteProjectDetail -->
    <v-dialog v-model="dialog" max-width="800px">
      <v-card>
        <v-card-title>
          <span class="headline">Paste Project Header - 2</span>
        </v-card-title>
        <v-card-text>
   <h1>{{projectId}}</h1>
  
          <v-text-field v-model="newProject.title" label="Title" required></v-text-field>

          <v-text-field v-model="newProject.tenure" label="Tenure" required></v-text-field>
          <v-text-field v-model="newProject.priceRange" label="Price Range" required></v-text-field>

          <v-text-field v-model="newProject.sizeRange" label="Size Range" required></v-text-field>

          <v-text-field v-model="newProject.totalUnit" label="Total Unit" required></v-text-field>

          <v-text-field v-model="newProject.totalStorey" label="Total Storey" required></v-text-field>

              </v-card-text>
        <v-card-actions>
          <v-btn color="primary" @click="submitProject">Submit</v-btn>
          <v-btn @click="closeDialog">Close</v-btn>
        </v-card-actions>
      </v-card>
      <v-btn @click="updateRow">Update Header Data</v-btn>

    </v-dialog>
    
     
  </v-container>
</template>

<script>
import { ref } from 'vue';

import { updateProjectRecPart2 } from '../utils/contactUtils'; // Import the mutation function

export default {
  name: 'ProjectListing',
  components: {

  },
  props: {
    projectId: {
      type: String,
      default: '', 
      required: true,
    },
  },
  setup(props) {
    const gridData = ref([]); // Holds grid data
    const headers = [
      { text: 'title', title: "title", value: 'title' },
      { text: 'description', title: "description", value: 'description' },

    ];

    const updateRow = async () => {
  try {
    const newLayout = {
      title: newProject.value.title,
      tenure: newProject.value.tenure,
      priceRange: newProject.value.priceRange,
      sizeRange: newProject.value.sizeRange,
      totalUnit: newProject.value.totalUnit,
      totalStorey: newProject.value.totalStorey,
    };
    
    await updateProjectRecPart2(props.projectId, newLayout);
    
    alert('Data successfully exported to Strapi!');
  } catch (error) {
    console.error('Error exporting data to Strapi:', error);
    alert('Failed to export data.');
  }
};


    const loading = ref(false);
    const error = ref(null);
    const dialog = ref(false);
    const selectedProjectId = ref(null);

    const newProject = ref({
title:"",	
tenure:"",		
priceRange:"",	
sizeRange:"",
totalUnit:""	,
totalStorey:"",

   
  
    });

     const handlePaste = (event) => {
      console.log("****1");
      const clipboardData = event.clipboardData || window.clipboardData;
      let pastedText = clipboardData.getData('text/plain');

      // Assuming tab-separated values for simplicity
      // pastedText = pastedText.replaceAll("\t\r\n", "~");
      // pastedText = pastedText.replaceAll("\r\n", "|");
      // pastedText = pastedText.replaceAll("Contract Expiry Date~Rebate", `Contract Expiry Date~-|Rebate`);
      const rows = pastedText.trim().split('\t\r\n').filter((row) => row.trim() !== '');

      const parsedData = rows.map((row) => {
        const columns = row.split('\t');
        return {
          title: columns[1] || '',
          description: columns[2] || '',
        };



      });
      console.log("****2");
      
      parsedData.forEach((item) => {
if (item.title.toLowerCase() === 'title') newProject.value.title = item.description;
if (item.title.toLowerCase() === 'tenure') newProject.value.tenure = item.description;
if (item.title.toLowerCase() === 'price range') newProject.value.priceRange = item.description;
if (item.title.toLowerCase() === 'size range') newProject.value.sizeRange = item.description;
if (item.title.toLowerCase() === 'total unit' || item.title.toLowerCase() === 'total units') newProject.value.totalUnit = item.description;
if (item.title.toLowerCase() === 'total storey') newProject.value.totalStorey = item.description;
      });

      gridData.value = [...gridData.value, ...parsedData];
      dialog.value = true;
    };



    const openDialog = (id) => {
      selectedProjectId.value = id;
      dialog.value = true;
    };

   

    const closeDialog = () => {
  console.log('Close button clicked');
  dialog.value = false;
  selectedProjectId.value = null;
  resetNewProject();
};

    const resetNewProject = () => {
      newProject.value = {
        
        title:'',
          tenure: '', // Assuming the first column is the project ID
          priceRange: '',
          sizeRange: '',
          totalUnit: "",
          totalStorey: "",



      };
    };

    const submitProject = () => {
      console.log('New Project Data:', newProject.value);
      closeDialog();
    };

    return {
      headers,
      loading,
      error,
      openDialog,
      closeDialog,
      dialog,
      selectedProjectId,
      newProject,
      submitProject,
      handlePaste,
      gridData,
      updateRow
    };
  },
};
</script>

<style scoped>
.elevation-1 {
  min-height: 300px;
}
</style>
