<template>
  <v-dialog v-model="dialog" max-width="600px">
    <v-card>
      <v-card-title>
        <span class="headline">Select a Date</span>
      </v-card-title>
      <v-card-text>
        <v-date-picker v-model="selectedDate"></v-date-picker>
      </v-card-text>
      <v-card-actions>
        <v-btn color="primary" @click="confirmDate">Confirm</v-btn>
        <v-btn color="grey" @click="closeDialog">Cancel</v-btn>
      </v-card-actions>
    </v-card>
  </v-dialog>
</template>

<script>
import { ref, defineComponent } from 'vue';

export default defineComponent({
  setup(_, { emit }) {
    const dialog = ref(false);
    const selectedDate = ref(null);

    const openDialog = () => {
      dialog.value = true;
    };

    const closeDialog = () => {
      dialog.value = false;
    };

    const confirmDate = () => {
      emit('date-selected', selectedDate.value);
      closeDialog();
    };

    return {
      dialog,
      selectedDate,
      openDialog,
      closeDialog,
      confirmDate,
    };
  },
});
</script>
